1	// Package service implements the WorkspaceService that orchestrates read queries
2	// and RPC calls to adapter-service.
3	package service
4	
5	import (
6		"context"
7		"encoding/json"
8		"errors"
9		"time"
10	
11		"github.com/tiendv89/workflow-backend/internal/adapter"
12		"github.com/tiendv89/workflow-backend/internal/database"
13		"github.com/tiendv89/workflow-backend/internal/domain"
14	)
15	
16	// DatabaseReader is the read-only interface over the shared PostgreSQL schema.
17	type DatabaseReader interface {
18		ListWorkspaces(ctx context.Context) ([]database.Workspace, error)
19		GetWorkspace(ctx context.Context, workspaceID string) (database.Workspace, error)
20		GetGitHubSource(ctx context.Context, workspaceID string) (database.WorkspaceGitHubSource, error)
21		ListLatestSyncRunsPerWorkspace(ctx context.Context) ([]database.WorkspaceSyncRun, error)
22		GetLatestSyncRun(ctx context.Context, workspaceID string) (database.WorkspaceSyncRun, error)
23		ListWorkspaceFeatures(ctx context.Context, workspaceID string) ([]database.WorkspaceFeature, error)
24		GetWorkspaceFeature(ctx context.Context, workspaceID, featureID string) (database.WorkspaceFeature, error)
25		ListFeatureDocuments(ctx context.Context, workspaceID, featureID string) ([]database.WorkspaceFeatureDocument, error)
26		ListFeatureTasks(ctx context.Context, workspaceID, featureID string) ([]database.WorkspaceTask, error)
27		ListWorkspaceTasks(ctx context.Context, workspaceID string) ([]database.WorkspaceTask, error)
28		GetWorkspaceTask(ctx context.Context, workspaceID, featureID, taskID string) (database.WorkspaceTask, error)
29		ListActivityEvents(ctx context.Context, workspaceID, featureID, taskID string) ([]database.WorkspaceActivityEvent, error)
30	}
31	
32	// AdapterCaller issues RPC calls to adapter-service for write operations.
33	type AdapterCaller interface {
34		ImportWorkspace(ctx context.Context, req adapter.ImportRequest) (string, error)
35		SyncWorkspace(ctx context.Context, workspaceID string) error
36	}
37	
38	// WorkspaceService orchestrates reads from PostgreSQL and calls to adapter-service.
39	type WorkspaceService struct {
40		db             DatabaseReader
41		adapter        AdapterCaller
42		staleThreshold time.Duration
43	}
44	
45	// New creates a new WorkspaceService.
46	func New(db DatabaseReader, adapterClient AdapterCaller, staleThreshold time.Duration) *WorkspaceService {
47		return &WorkspaceService{
48			db:             db,
49			adapter:        adapterClient,
50			staleThreshold: staleThreshold,
51		}
52	}
53	
54	// ListWorkspaces returns summary rows for all saved workspaces with source state.
55	func (s *WorkspaceService) ListWorkspaces(ctx context.Context) ([]domain.WorkspaceSummary, error) {
56		rows, err := s.db.ListWorkspaces(ctx)
57		if err != nil {
58			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
59		}
60	
61		// Batch-load latest sync run per workspace to avoid N+1 queries.
62		allRuns, _ := s.db.ListLatestSyncRunsPerWorkspace(ctx)
63		runMap := make(map[string]database.WorkspaceSyncRun, len(allRuns))
64		for _, run := range allRuns {
65			runMap[database.UUIDString(run.WorkspaceID)] = run
66		}
67	
68		out := make([]domain.WorkspaceSummary, 0, len(rows))
69		for _, r := range rows {
70			wsID := database.UUIDString(r.ID)
71			srcRun, ok := runMap[wsID]
72			var ss domain.SourceState
73			if ok {
74				ss = toSourceState(&srcRun, s.staleThreshold)
75			} else {
76				ss = domain.DeriveSourceState(nil, s.staleThreshold)
77			}
78	
79			repoURL := s.githubRepoURL(ctx, wsID)
80			out = append(out, domain.WorkspaceSummary{
81				ID:          wsID,
82				Name:        r.Name,
83				Slug:        r.Slug,
84				RepoURL:     repoURL,
85				SourceState: ss,
86				UpdatedAt:   r.UpdatedAt.Time,
87			})
88		}
89		return out, nil
90	}
91	
92	// ImportWorkspace calls adapter-service to import a workspace then returns its detail.
93	func (s *WorkspaceService) ImportWorkspace(ctx context.Context, input domain.ImportInput) (*domain.WorkspaceDetail, domain.SourceError) {
94		workspaceID, err := s.adapter.ImportWorkspace(ctx, adapter.ImportRequest{
95			RepoURL:       input.RepoURL,
96			DefaultBranch: input.DefaultBranch,
97			Name:          input.Name,
98		})
99		if err != nil {
100			if se, ok := err.(domain.SourceError); ok {
101				return nil, se
102			}
103			return nil, domain.NewAdapterError(domain.ErrAdapterInternal, err.Error())
104		}
105	
106		detail, dbErr := s.GetWorkspace(ctx, workspaceID)
107		if dbErr != (domain.SourceError{}) {
108			return nil, dbErr
109		}
110		return detail, domain.SourceError{}
111	}
112	
113	// GetWorkspace returns full workspace detail with features, tasks, and source state.
114	func (s *WorkspaceService) GetWorkspace(ctx context.Context, workspaceID string) (*domain.WorkspaceDetail, domain.SourceError) {
115		ws, err := s.db.GetWorkspace(ctx, workspaceID)
116		if err != nil {
117			if errors.Is(err, database.ErrNotFound) {
118				return nil, domain.NewDatabaseNotFound("workspace", workspaceID)
119			}
120			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
121		}
122	
123		wsID := database.UUIDString(ws.ID)
124	
125		features, err := s.db.ListWorkspaceFeatures(ctx, wsID)
126		if err != nil {
127			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
128		}
129	
130		tasks, err := s.db.ListWorkspaceTasks(ctx, wsID)
131		if err != nil {
132			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
133		}
134	
135		// Count tasks per feature for FeatureSummary.
136		taskCountsByFeature := make(map[string]map[string]int)
137		for _, t := range tasks {
138			if _, ok := taskCountsByFeature[t.FeatureID]; !ok {
139				taskCountsByFeature[t.FeatureID] = make(map[string]int)
140			}
141			taskCountsByFeature[t.FeatureID]["total"]++
142			if t.Status != nil {
143				taskCountsByFeature[t.FeatureID][*t.Status]++
144			}
145		}
146	
147		syncRun, err := s.db.GetLatestSyncRun(ctx, wsID)
148		var ss domain.SourceState
149		if errors.Is(err, database.ErrNotFound) || err != nil {
150			ss = domain.DeriveSourceState(nil, s.staleThreshold)
151		} else {
152			ss = toSourceState(&syncRun, s.staleThreshold)
153		}
154	
155		featureSummaries := make([]domain.FeatureSummary, 0, len(features))
156		for _, f := range features {
157			counts := taskCountsByFeature[f.FeatureID]
158			featureSummaries = append(featureSummaries, domain.FeatureSummary{
159				FeatureID:    f.FeatureID,
160				Title:        f.Title,
161				Status:       derefStr(f.FeatureStatus),
162				CurrentStage: derefStr(f.CurrentStage),
163				UpdatedAt:    f.UpdatedAt.Time,
164				TaskCounts: domain.TaskCounts{
165					Total:      counts["total"],
166					Done:       counts["done"],
167					InProgress: counts["in_progress"],
168					Blocked:    counts["blocked"],
169					Ready:      counts["ready"],
170					Todo:       counts["todo"],
171				},
172			})
173		}
174	
175		taskSummaries := make([]domain.TaskSummary, 0, len(tasks))
176		for _, t := range tasks {
177			taskSummaries = append(taskSummaries, toTaskSummary(t))
178		}
179	
180		repoURL := s.githubRepoURL(ctx, wsID)
181		return &domain.WorkspaceDetail{
182			WorkspaceSummary: domain.WorkspaceSummary{
183				ID:          wsID,
184				Name:        ws.Name,
185				Slug:        ws.Slug,
186				RepoURL:     repoURL,
187				SourceState: ss,
188				UpdatedAt:   ws.UpdatedAt.Time,
189			},
190			Features: featureSummaries,
191			Tasks:    taskSummaries,
192		}, domain.SourceError{}
193	}
194	
195	// SyncWorkspace calls adapter-service to re-sync a workspace then returns updated detail.
196	// On sync failure with cached data, returns cached data marked stale.
197	// On sync failure without cached data, returns a structured source error.
198	func (s *WorkspaceService) SyncWorkspace(ctx context.Context, workspaceID string) (*domain.WorkspaceDetail, domain.SourceError) {
199		if err := s.adapter.SyncWorkspace(ctx, workspaceID); err != nil {
200			// Sync failed — try to return cached data with stale marker.
201			detail, dbErr := s.GetWorkspace(ctx, workspaceID)
202			if dbErr != (domain.SourceError{}) {
203				// No cached data — return the adapter error.
204				if se, ok := err.(domain.SourceError); ok {
205					return nil, se
206				}
207				return nil, domain.NewAdapterError(domain.ErrAdapterInternal, err.Error())
208			}
209			// Return stale cached data.
210			detail.SourceState.Stale = true
211			if se, ok := err.(domain.SourceError); ok {
212				detail.SourceState.ErrorCode = string(se.Code)
213				detail.SourceState.ErrorMessage = se.Message
214			}
215			return detail, domain.SourceError{}
216		}
217	
218		return s.GetWorkspace(ctx, workspaceID)
219	}
220	
221	// GetFeature returns feature detail with documents, tasks, and activity.
222	func (s *WorkspaceService) GetFeature(ctx context.Context, workspaceID, featureID string) (*domain.FeatureDetail, domain.SourceError) {
223		// Verify workspace exists.
224		ws, err := s.db.GetWorkspace(ctx, workspaceID)
225		if err != nil {
226			if errors.Is(err, database.ErrNotFound) {
227				return nil, domain.NewDatabaseNotFound("workspace", workspaceID)
228			}
229			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
230		}
231		wsID := database.UUIDString(ws.ID)
232	
233		feat, err := s.db.GetWorkspaceFeature(ctx, wsID, featureID)
234		if err != nil {
235			if errors.Is(err, database.ErrNotFound) {
236				return nil, domain.NewDatabaseNotFound("feature", featureID)
237			}
238			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
239		}
240	
241		docs, err := s.db.ListFeatureDocuments(ctx, wsID, featureID)
242		if err != nil {
243			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
244		}
245	
246		tasks, err := s.db.ListFeatureTasks(ctx, wsID, featureID)
247		if err != nil {
248			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
249		}
250	
251		activity, err := s.db.ListActivityEvents(ctx, wsID, featureID, "")
252		if err != nil {
253			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
254		}
255	
256		syncRun, err := s.db.GetLatestSyncRun(ctx, wsID)
257		var ss domain.SourceState
258		if errors.Is(err, database.ErrNotFound) || err != nil {
259			ss = domain.DeriveSourceState(nil, s.staleThreshold)
260		} else {
261			ss = toSourceState(&syncRun, s.staleThreshold)
262		}
263	
264		counts := countTasks(tasks)
265		docLinks := make([]domain.DocumentLink, 0, len(docs))
266		for _, d := range docs {
267			docLinks = append(docLinks, domain.DocumentLink{
268				DocumentType: d.DocumentType,
269				SourcePath:   d.SourcePath,
270				URL:          derefStr(d.URL),
271			})
272		}
273	
274		taskSummaries := make([]domain.TaskSummary, 0, len(tasks))
275		for _, t := range tasks {
276			taskSummaries = append(taskSummaries, toTaskSummary(t))
277		}
278	
279		activityEvents := make([]domain.ActivityEvent, 0, len(activity))
280		for _, a := range activity {
281			activityEvents = append(activityEvents, toActivityEvent(a))
282		}
283	
284		return &domain.FeatureDetail{
285			FeatureSummary: domain.FeatureSummary{
286				FeatureID:    feat.FeatureID,
287				Title:        feat.Title,
288				Status:       derefStr(feat.FeatureStatus),
289				CurrentStage: derefStr(feat.CurrentStage),
290				UpdatedAt:    feat.UpdatedAt.Time,
291				TaskCounts:   counts,
292			},
293			WorkspaceID: workspaceID,
294			Documents:   docLinks,
295			Tasks:       taskSummaries,
296			Activity:    activityEvents,
297			SourceState: ss,
298		}, domain.SourceError{}
299	}
300	
301	// ListFeatureTasks returns task summaries for all tasks in a feature.
302	func (s *WorkspaceService) ListFeatureTasks(ctx context.Context, workspaceID, featureID string) ([]domain.TaskSummary, domain.SourceError) {
303		ws, err := s.db.GetWorkspace(ctx, workspaceID)
304		if err != nil {
305			if errors.Is(err, database.ErrNotFound) {
306				return nil, domain.NewDatabaseNotFound("workspace", workspaceID)
307			}
308			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
309		}
310		wsID := database.UUIDString(ws.ID)
311	
312		tasks, err := s.db.ListFeatureTasks(ctx, wsID, featureID)
313		if err != nil {
314			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
315		}
316	
317		out := make([]domain.TaskSummary, 0, len(tasks))
318		for _, t := range tasks {
319			out = append(out, toTaskSummary(t))
320		}
321		return out, domain.SourceError{}
322	}
323	
324	// GetTask returns full task detail including activity.
325	func (s *WorkspaceService) GetTask(ctx context.Context, workspaceID, featureID, taskID string) (*domain.TaskDetail, domain.SourceError) {
326		ws, err := s.db.GetWorkspace(ctx, workspaceID)
327		if err != nil {
328			if errors.Is(err, database.ErrNotFound) {
329				return nil, domain.NewDatabaseNotFound("workspace", workspaceID)
330			}
331			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
332		}
333		wsID := database.UUIDString(ws.ID)
334	
335		t, err := s.db.GetWorkspaceTask(ctx, wsID, featureID, taskID)
336		if err != nil {
337			if errors.Is(err, database.ErrNotFound) {
338				return nil, domain.NewDatabaseNotFound("task", taskID)
339			}
340			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
341		}
342	
343		activity, err := s.db.ListActivityEvents(ctx, wsID, featureID, taskID)
344		if err != nil {
345			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
346		}
347	
348		activityEvents := make([]domain.ActivityEvent, 0, len(activity))
349		for _, a := range activity {
350			activityEvents = append(activityEvents, toActivityEvent(a))
351		}
352	
353		var dependsOn []string
354		if t.DependsOn != nil {
355			_ = json.Unmarshal(t.DependsOn, &dependsOn)
356		}
357		if dependsOn == nil {
358			dependsOn = []string{}
359		}
360	
361		var execution map[string]interface{}
362		if t.Execution != nil {
363			_ = json.Unmarshal(t.Execution, &execution)
364		}
365		execCtx := domain.ExecutionContext{}
366		if execution != nil {
367			if v, ok := execution["actor_type"].(string); ok {
368				execCtx.ActorType = v
369			}
370			if v, ok := execution["last_updated_by"].(string); ok {
371				execCtx.LastUpdatedBy = v
372			}
373			if v, ok := execution["last_updated_at"].(string); ok {
374				execCtx.LastUpdatedAt = v
375			}
376		}
377	
378		prRefs := parsePRRefs(t.Pr, t.WorkspacePr, t.FeatureID)
379	
380		return &domain.TaskDetail{
381			TaskSummary: toTaskSummary(t),
382			WorkspaceID: workspaceID,
383			DependsOn:   dependsOn,
384			Execution:   execCtx,
385			PRRefs:      prRefs,
386			Activity:    activityEvents,
387		}, domain.SourceError{}
388	}
389	
390	// ListActivity returns activity events for a workspace.
391	func (s *WorkspaceService) ListActivity(ctx context.Context, workspaceID string, scope domain.ActivityScope) ([]domain.ActivityEvent, domain.SourceError) {
392		ws, err := s.db.GetWorkspace(ctx, workspaceID)
393		if err != nil {
394			if errors.Is(err, database.ErrNotFound) {
395				return nil, domain.NewDatabaseNotFound("workspace", workspaceID)
396			}
397			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
398		}
399		wsID := database.UUIDString(ws.ID)
400	
401		events, err := s.db.ListActivityEvents(ctx, wsID, scope.FeatureID, scope.TaskID)
402		if err != nil {
403			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
404		}
405	
406		out := make([]domain.ActivityEvent, 0, len(events))
407		for _, a := range events {
408			out = append(out, toActivityEvent(a))
409		}
410		return out, domain.SourceError{}
411	}
412	
413	// githubRepoURL fetches the GitHub repo URL for a workspace from workspace_github_sources.
414	func (s *WorkspaceService) githubRepoURL(ctx context.Context, workspaceID string) string {
415		src, err := s.db.GetGitHubSource(ctx, workspaceID)
416		if err != nil {
417			return ""
418		}
419		return src.RepoURL
420	}
421	
422	// --- conversion helpers ---
423	
424	func toSourceState(run *database.WorkspaceSyncRun, threshold time.Duration) domain.SourceState {
425		if run == nil {
426			return domain.DeriveSourceState(nil, threshold)
427		}
428		sr := &domain.SyncRun{
429			ID:          database.UUIDString(run.ID),
430			WorkspaceID: database.UUIDString(run.WorkspaceID),
431			Trigger:     run.Trigger,
432			Mode:        run.Mode,
433			Status:      domain.SyncStatus(run.Status),
434			StartedAt:   run.StartedAt.Time,
435		}
436		if run.FinishedAt.Valid {
437			t := run.FinishedAt.Time
438			sr.FinishedAt = &t
439		}
440		if run.CommitSha != nil {
441			sr.CommitSHA = *run.CommitSha
442		}
443		if run.ErrorCode != nil {
444			sr.ErrorCode = *run.ErrorCode
445		}
446		if run.ErrorMessage != nil {
447			sr.ErrorMsg = *run.ErrorMessage
448		}
449		return domain.DeriveSourceState(sr, threshold)
450	}
451	
452	func toTaskSummary(t database.WorkspaceTask) domain.TaskSummary {
453		isBlocked := t.Status != nil && *t.Status == "blocked"
454		return domain.TaskSummary{
455			TaskID:        t.TaskID,
456			FeatureID:     t.FeatureID,
457			Title:         t.Title,
458			Status:        derefStr(t.Status),
459			Repo:          derefStr(t.Repo),
460			Branch:        derefStr(t.Branch),
461			IsBlocked:     isBlocked,
462			BlockedReason: derefStr(t.BlockedReason),
463		}
464	}
465	
466	func toActivityEvent(a database.WorkspaceActivityEvent) domain.ActivityEvent {
467		e := domain.ActivityEvent{
468			Action:    derefStr(a.Action),
469			Scope:     a.ScopeType,
470			Actor:     derefStr(a.Actor),
471			Note:      derefStr(a.Note),
472			FeatureID: derefStr(a.FeatureID),
473			TaskID:    derefStr(a.TaskID),
474		}
475		if a.OccurredAt != nil {
476			if t, err := time.Parse(time.RFC3339, *a.OccurredAt); err == nil {
477				e.OccurredAt = t
478			}
479		}
480		return e
481	}
482	
483	func countTasks(tasks []database.WorkspaceTask) domain.TaskCounts {
484		var counts domain.TaskCounts
485		for _, t := range tasks {
486			counts.Total++
487			if t.Status != nil {
488				switch *t.Status {
489				case "done":
490					counts.Done++
491				case "in_progress":
492					counts.InProgress++
493				case "blocked":
494					counts.Blocked++
495				case "ready":
496					counts.Ready++
497				case "todo":
498					counts.Todo++
499				}
500			}
501		}
502		return counts
503	}
504	
505	func parsePRRefs(prData, workspacePRData []byte, featureID string) []domain.PullRequestRef {
506		var refs []domain.PullRequestRef
507	
508		var pr map[string]interface{}
509		if prData != nil {
510			if json.Unmarshal(prData, &pr) == nil {
511				if url, ok := pr["url"].(string); ok && url != "" {
512					status, _ := pr["status"].(string)
513					refs = append(refs, domain.PullRequestRef{
514						Label:  "Implementation PR",
515						URL:    url,
516						Status: status,
517						Repo:   featureID,
518					})
519				}
520			}
521		}
522	
523		var wsPR map[string]interface{}
524		if workspacePRData != nil {
525			if json.Unmarshal(workspacePRData, &wsPR) == nil {
526				if url, ok := wsPR["url"].(string); ok && url != "" {
527					status, _ := wsPR["status"].(string)
528					refs = append(refs, domain.PullRequestRef{
529						Label:  "Workspace PR",
530						URL:    url,
531						Status: status,
532						Repo:   "management-repo",
533					})
534				}
535			}
536		}
537		return refs
538	}
539	
540	func derefStr(s *string) string {
541		if s == nil {
542			return ""
543		}
544		return *s
545	}
