	db := &fakeDB{
		workspaces: []database.Workspace{ws},
		tasks:      []database.WorkspaceTask{task},
	}
	svc := newService(db, &fakeAdapter{})

	detail, se := svc.GetTask(context.Background(), testWSID, "feature-1", "T1")
	if se != (domain.SourceError{}) {
